script:
(function () {
  'use strict';
  // Streamlined debt snowball: up to five debts and one fixed total monthly payment.
  // Each month every open debt is charged interest = balance x APR / 12 (rounded to the cent)
  // and paid its own minimum (capped at what it owes). Whatever is left of the total payment
  // goes to the open debt with the smallest starting balance (ties -> higher APR, then the
  // order listed), spilling to the next debt if that one clears mid-month. As debts are cleared
  // their minimums stay inside the fixed total, so the payment on the focus debt grows.
  // Verified (scratchpad b6credit/ss.test.js):
  //   one debt of $10,000 at 12% with a $222.45 total -> 60 months (closed-form level payment
  //   $222.44); two 0% debts ($500 min $50, $1,000 min $50) with a $200 total -> the $500 debt
  //   clears in month 4 ($150 x 3 + $50) and the plan ends in month 8 = ceil(1,500 / 200);
  //   with 0% rates the plan always ends at ceil(total debt / payment); the default three
  //   debts give the same months as the site's full snowball calculator logic with
  //   extra = total - minimums; a total below the minimums or below the interest is rejected.

  // ---- Calculation ----
  var MAX_MONTHS = 1200;
  function cents(x) { return Math.round(x * 100) / 100; }

  function snowballOrder(debts) {
    return debts.map(function (d, i) { return i; }).sort(function (a, b) {
      return (debts[a].balance - debts[b].balance) || (debts[b].apr - debts[a].apr) || (a - b);
    });
  }

  // debts: [{ balance, apr (decimal), min }]; total: fixed monthly payment for all debts.
  function plan(debts, total) {
    var n = debts.length, bal = debts.map(function (d) { return d.balance; });
    var order = snowballOrder(debts), paidOff = debts.map(function () { return 0; });
    var interestTotal = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var i, open = 0, avail = total;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var interest = cents(bal[i] * debts[i].apr / 12);
        bal[i] += interest; interestTotal += interest;
      }
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var pay = Math.min(debts[i].min, bal[i]);
        bal[i] = cents(bal[i] - pay); avail -= pay;
      }
      for (var k = 0; k < n && avail > 0.005; k++) {
        var j = order[k];
        if (bal[j] <= 0.005) continue;
        var more = Math.min(avail, bal[j]);
        bal[j] = cents(bal[j] - more); avail -= more;
      }
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) { bal[i] = 0; if (!paidOff[i]) paidOff[i] = m; } else open++;
      }
      if (!open) return { done: true, months: m, order: order, paidOff: paidOff, interest: interestTotal };
    }
    return { done: false, months: MAX_MONTHS, order: order, paidOff: paidOff, interest: interestTotal };
  }

  // ---- UI ----
  var ROWS = 5;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function readDebts() {
    var out = [], ok = true;
    for (var i = 1; i <= ROWS; i++) {
      var balEl = document.getElementById('ssbBal' + i), aprEl = document.getElementById('ssbApr' + i), minEl = document.getElementById('ssbMin' + i);
      var name = document.getElementById('ssbName' + i).value.trim() || ('Debt ' + i);
      if (balEl.value.trim() === '' || parseFloat(balEl.value) === 0) {
        [balEl, aprEl, minEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        continue;
      }
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value), min = parseFloat(minEl.value);
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badMin = isNaN(min) || min <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      minEl.setAttribute('aria-invalid', String(badMin));
      if (badBal || badApr || badMin) { ok = false; continue; }
      out.push({ name: name, balance: bal, apr: apr / 100, min: min });
    }
    return { ok: ok, debts: out };
  }

  function clearResults() {
    set('ssbDate', '–'); set('ssbMonths', '–'); set('ssbMonthsNote', ''); set('ssbNote', '');
    clearBody('ssbOrder');
  }

  function update() {
    var error = document.getElementById('ssbError');
    var total = parseFloat(document.getElementById('ssbTotal').value);
    var input = readDebts(), problem = '';
    var mins = input.debts.reduce(function (s, d) { return s + d.min; }, 0);
    if (!input.ok) problem = 'Check the highlighted debts: a balance above $0, an APR from 0 to 100% and a minimum above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(total) || total <= 0) problem = 'Enter the total you can pay each month.';
    else if (total < mins - 0.005) problem = 'Your total payment must cover the minimums, which add up to ' + money.format(mins) + '.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    var debts = input.debts, r = plan(debts, total);
    if (!r.done) {
      error.hidden = false;
      error.textContent = 'This payment does not keep up with the interest, so the debts are not cleared within 100 years. Raise the total.';
      clearResults();
      return;
    }
    error.hidden = true; error.textContent = '';
    set('ssbDate', dateAfter(r.months));
    set('ssbMonths', String(r.months));
    set('ssbMonthsNote', duration(r.months) + ', paying ' + money.format(total) + ' a month.');
    var body = clearBody('ssbOrder');
    r.order.forEach(function (i, step) {
      var tr = document.createElement('tr');
      [String(step + 1), debts[i].name, money.format(debts[i].balance), dateAfter(r.paidOff[i]) + ' (month ' + r.paidOff[i] + ')'].forEach(function (t) {
        var td = document.createElement('td'); td.textContent = t; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
    var extra = total - mins;
    set('ssbNote', 'Minimums ' + money.format(mins) + ' + ' + money.format(extra) + ' extra to the smallest balance. Total interest ' + money.format(r.interest) + '.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ssbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
